const MASTER_SUBAGENT: &str = r#"Project role: Master's subagent. You make no Project changes: the runtime withholds edit, write and patch and allows only read-only shell commands; member Sessions make every Project change. Do read-only research, review and evidence verification for your parent, report results and blockers to it with evidence and a recommendation, and preserve native permission, question and review gates; coordination messages are not native approvals."#;

const REMOVED: &str =
    "The Project coordination role above no longer applies to this Session. Disregard it.";

pub fn initial(role: Role, coordinating: bool) -> LosslessString {
    match role {
        Role::Master => format!("Project role: Master. Route Project work through recorded owners; use Master-only controls for enrollment and ownership, never to dispatch or steer member work. Assign and transfer supervisor ownership, keep read-only oversight, and handle escalations and integration for delegated work while preserving Session and Project histories without deleting history or cancelling active work.\n\nAfter verifying delivery and its evidence, have the recorded owners verify that finished members are idle, have no outstanding work or requests, and are not needed for reuse. Have them arrange archival through the authorized role. Archive through an authorized native Session control and verify the archive time; do not issue a shell mutation as coordinator. Archiving a member releases its ownership and keeps its membership; use the Master-only detach or release control if the lifecycle calls for a separate membership or ownership change. Only after ownership clears and the supervisor's task settles, archive the finished supervisor if it is no longer needed. Keep active, waiting and reusable Sessions open. Preserve Session history, evidence and dependency links. If a native control refuses, keep the records intact and report the exact gate.\n\n{CONTENT}").into(),
        Role::Supervisor => format!("Project role: supervisor. Act only on the Sessions you own in the recorded Project graph: reuse a suitable owned member when available and steer or update owned member Sessions within authorized routes; you cannot call the `project` tool's Master-only create, attach, assign (including transfers), release, or remove operations. Stay attached after completion until the Master releases or transfers ownership, the member leaves or closes, or you are cancelled, failed or lost; executor children inherit none of your authority.\n\n{CONTENT}").into(),
        Role::Executor if coordinating => MASTER_SUBAGENT.into(),
        Role::Executor => EXECUTOR.into(),
    }
}
pub fn changed(previous: &LosslessString, role: Role, coordinating: bool) -> LosslessString {
    let current = initial(role, coordinating);
    if role == Role::Executor
        && previous
            .to_utf8()
            .is_ok_and(|text| text.contains("Coordinate and supervise only"))
    {
        return format!("{REMOVED}\n{}", current.to_utf8().unwrap_or_default()).into();
    }
    current
}
pub fn removed() -> LosslessString {
    REMOVED.into()
}

pub fn source(role: Role, coordinating: bool) -> Source {
    let text = |value: &JsonValue| match value {
        JsonValue::String(text) => Some(text.clone()),
        _ => None,
    };
    Source {
        key: instruction::Key::decode(&JsonValue::String(KEY.into()))
            .expect("coordination instruction key"),
        read: Arc::new(move || {
            Box::pin(async move {
                Ok(Observation::Value(JsonValue::String(initial(
                    role,
                    coordinating,
                ))))
            })
        }),
        initial: Arc::new(move |value| text(value)),
        changed: Arc::new(move |previous, _| Some(changed(&text(previous)?, role, coordinating))),
        removed: Some(Arc::new(|_| Some(removed()))),
    }
}
